3	namespace App\Jobs\Shopify;
4	
5	use App\Models\Core\Professional\ProfessionalIntegration;
6	use App\Services\Shopify\Client\ShopifyAdminClient;
7	use Illuminate\Bus\Queueable;
8	use Illuminate\Contracts\Queue\ShouldBeUnique;
9	use Illuminate\Contracts\Queue\ShouldQueue;
10	use Illuminate\Foundation\Bus\Dispatchable;
11	use Illuminate\Queue\InteractsWithQueue;
12	use Illuminate\Queue\SerializesModels;
13	use Illuminate\Support\Arr;
14	use Illuminate\Support\Facades\Log;
15	
16	// V2: Core. Registers all Shopify webhooks (functional + GDPR) via GraphQL on install. Idempotent — skips already-registered topics.
17	class RegisterShopifyWebhooksJob implements ShouldBeUnique, ShouldQueue
18	{
19	    use Dispatchable, InteractsWithQueue, Queueable, SerializesModels;
20	
21	    public int $tries = 3;
22	
23	    public int $timeout = 300;
24	
25	    public int $uniqueFor = 300;
26	
27	    public function uniqueId(): string
28	    {
29	        return $this->integrationId;
30	    }
31	
32	    public function backoff(): array
33	    {
34	        return [10, 30, 60];
35	    }
36	
37	    private const WEBHOOK_SUBSCRIPTION_CREATE = <<<'GRAPHQL'
38	    mutation webhookSubscriptionCreate($topic: WebhookSubscriptionTopic!, $webhookSubscription: WebhookSubscriptionInput!) {
39	      webhookSubscriptionCreate(topic: $topic, webhookSubscription: $webhookSubscription) {
40	        webhookSubscription {
41	          id
42	          topic
43	          endpoint {
44	            ... on WebhookHttpEndpoint {
45	              callbackUrl
46	            }
47	          }
48	        }
49	        userErrors {
50	          field
51	          message
52	        }
53	      }
54	    }
55	    GRAPHQL;
56	
57	    private const WEBHOOK_SUBSCRIPTIONS_QUERY = <<<'GRAPHQL'
58	    query webhookSubscriptions($topic: WebhookSubscriptionTopic!, $first: Int!) {
59	      webhookSubscriptions(topics: [$topic], first: $first) {
60	        edges {
61	          node {
62	            id
63	            topic
64	            endpoint {
65	              ... on WebhookHttpEndpoint {
66	                callbackUrl
67	              }
68	            }
69	          }
70	        }
71	      }
72	    }
73	    GRAPHQL;
74	
75	    // GDPR compliance topics (CUSTOMERS_DATA_REQUEST, CUSTOMERS_REDACT, SHOP_REDACT) cannot be
76	    // registered via the GraphQL API — they are handled via shopify.app.toml compliance_topics.
77	    private const WEBHOOKS = [
78	        'ORDERS_PAID'     => '/api/webhooks/shopify/orders-paid',
79	        'ORDERS_UPDATED'  => '/api/webhooks/shopify/orders-updated',
80	        'APP_UNINSTALLED' => '/api/webhooks/shopify/app-uninstalled',
81	        'SHOP_UPDATE'     => '/api/webhooks/shopify/shop-update',
82	        // Triggers a brand design re-sync whenever the merchant publishes a new theme.
83	        'THEMES_PUBLISH'  => '/api/webhooks/shopify/themes-publish',
84	    ];
85	
86	    /** Populated by handle() — not serialized. */
87	    private ShopifyAdminClient $client;
88	
89	    public function __construct(
90	        public string $integrationId
91	    ) {
92	        $this->onQueue('integrations');
93	    }
94	
95	    public function handle(ShopifyAdminClient $client): void
96	    {
97	        $this->client = $client;
98	        $integration = ProfessionalIntegration::query()
99	            ->where('id', $this->integrationId)
100	            ->where('provider', ProfessionalIntegration::PROVIDER_SHOPIFY)
101	            ->first();
102	
103	        if (! $integration) {
104	            return;
105	        }
106	
107	        $metadata = is_array($integration->provider_metadata) ? $integration->provider_metadata : [];
108	        $shopDomain = trim((string) Arr::get($metadata, 'shop_domain', ''));
109	        $accessToken = trim((string) $integration->access_token);
110	
111	        if ($shopDomain === '' || $accessToken === '' || ! preg_match('/^[a-z0-9\-]+\.myshopify\.com$/', $shopDomain)) {
112	            $integration->mergeProviderMetadata([
113	                'webhooks_state' => 'failed',
114	                'webhooks_error' => 'Missing or invalid shop domain or access token.',
115	            ]);
116	
117	            return;
118	        }
119	
120	        $apiVersion = trim((string) config('services.shopify.api_version', '2025-01'));
121	        $baseUrl = rtrim((string) config('app.url'), '/');
122	        $results = [];
123	        $allSucceeded = true;
124	
125	        foreach (self::WEBHOOKS as $topic => $path) {
126	            $callbackUrl = $baseUrl.$path;
127	
128	            try {
129	                $existing = $this->findExistingWebhook($shopDomain, $accessToken, $apiVersion, $topic, $callbackUrl);
130	
131	                if ($existing) {
132	                    $results[$topic] = ['state' => 'registered', 'webhook_id' => $existing, 'existed' => true];
133	
134	                    continue;
135	                }
136	
137	                $webhookId = $this->createWebhook($shopDomain, $accessToken, $apiVersion, $topic, $callbackUrl);
138	                $results[$topic] = ['state' => 'registered', 'webhook_id' => $webhookId, 'existed' => false];
139	            } catch (\Throwable $e) {
140	                Log::error('Failed to register Shopify webhook.', [
141	                    'integration_id' => $this->integrationId,
142	                    'shop_domain' => $shopDomain,
143	                    'topic' => $topic,
144	                    'error' => $e->getMessage(),
145	                ]);
146	
147	                $results[$topic] = ['state' => 'failed', 'error' => $e->getMessage()];
148	                $allSucceeded = false;
149	            }
150	        }
151	
152	        $integration->mergeProviderMetadata([
153	            'webhooks_state' => $allSucceeded ? 'registered' : 'partial',
154	            'webhooks_registered_at' => now()->toIso8601String(),
155	            'webhooks_results' => $results,
156	            // Backward-compat keys
157	            'webhook_registration_state' => $allSucceeded ? 'registered' : 'partial',
158	            'webhook_registration_last_attempt_at' => now()->toIso8601String(),
159	        ]);
160	
161	        Log::info('Shopify webhook registration complete.', [
162	            'integration_id' => $this->integrationId,
163	            'shop_domain' => $shopDomain,
164	            'all_succeeded' => $allSucceeded,
165	            'topics_registered' => collect($results)->where('state', 'registered')->count(),
166	            'topics_failed' => collect($results)->where('state', 'failed')->count(),
167	        ]);
168	    }
169	
170	    private function findExistingWebhook(string $shopDomain, string $accessToken, string $apiVersion, string $topic, string $callbackUrl): ?string
171	    {
172	        $data = $this->queryShopify($shopDomain, $accessToken, $apiVersion, self::WEBHOOK_SUBSCRIPTIONS_QUERY, [
173	            'topic' => $topic,
174	            'first' => 10,
175	        ]);
176	
177	        $edges = Arr::get($data, 'webhookSubscriptions.edges', []);
178	        if (! is_array($edges)) {
179	            return null;
180	        }
181	
182	        foreach ($edges as $edge) {
183	            $node = $edge['node'] ?? null;
184	            if (! is_array($node)) {
185	                continue;
186	            }
187	
188	            $existingUrl = trim((string) Arr::get($node, 'endpoint.callbackUrl', ''));
189	            if (strcasecmp($existingUrl, $callbackUrl) === 0) {
190	                return (string) $node['id'];
191	            }
192	        }
193	
194	        return null;
195	    }
196	
197	    private function createWebhook(string $shopDomain, string $accessToken, string $apiVersion, string $topic, string $callbackUrl): string
198	    {
199	        $data = $this->queryShopify($shopDomain, $accessToken, $apiVersion, self::WEBHOOK_SUBSCRIPTION_CREATE, [
200	            'topic' => $topic,
201	            'webhookSubscription' => [
202	                'callbackUrl' => $callbackUrl,
203	                'format' => 'JSON',
204	            ],
205	        ]);
206	
207	        $userErrors = Arr::get($data, 'webhookSubscriptionCreate.userErrors', []);
208	        if (is_array($userErrors) && $userErrors !== []) {
209	            $message = (string) Arr::get($userErrors, '0.message', 'Unknown webhook creation error.');
210	            throw new \RuntimeException("Shopify webhook creation failed for {$topic}: {$message}");
211	        }
212	
213	        $webhookId = Arr::get($data, 'webhookSubscriptionCreate.webhookSubscription.id');
214	        if (! $webhookId) {
215	            throw new \RuntimeException("Shopify webhook was created for {$topic} but no ID was returned.");
216	        }
217	
218	        return (string) $webhookId;
219	    }
220	
221	    private function queryShopify(string $shopDomain, string $accessToken, string $apiVersion, string $query, array $variables = []): array
222	    {
223	        $response = $this->client->graphql(
224	            $shopDomain,
225	            $accessToken,
226	            $apiVersion,
227	            $query,
228	            $variables,
229	        );
230	
231	        return is_array($response->json('data')) ? $response->json('data') : [];
232	    }
233	}
