5	use App\Exceptions\Shopify\ShopifyGraphQLException;
6	use App\Exceptions\Shopify\ShopifyThrottledException;
7	use App\Exceptions\Shopify\ShopifyTransportException;
8	use Illuminate\Http\Client\ConnectionException;
9	use Illuminate\Http\Client\Response;
10	use Illuminate\Support\Facades\Http;
11	
12	/**
13	 * Single entry point for all Shopify Admin API calls.
14	 *
15	 * Handles:
16	 *   - GraphQL with throttle-aware in-process retries
17	 *   - REST with 429/Retry-After honouring
18	 *   - Bulk operation helpers with per-shop mutex
19	 *   - Typed exceptions that the queue's backoff() retry can handle
20	 *
21	 * Call sites pass shop_domain + access_token + api_version and get back
22	 * a standard Illuminate Http Response (or a throw). Throttle state is
23	 * tracked out-of-band via ShopifyBudgetTracker and reconciled from
24	 * extensions.cost.throttleStatus on every response.
25	 *
26	 * NOTE: budget pre-acquisition and THROTTLED retry are wired in the graphql()
27	 * method — see preAcquireBudget(), reconcileFromResponse(), and isThrottled().
28	 */
29	class ShopifyAdminClient
30	{
31	    public function __construct(
32	        private readonly ShopifyBudgetTracker $budget,
33	        private readonly ShopifyCostTracker $cost,
34	        private readonly ShopifyMetrics $metrics,
35	        private readonly ShopifyBulkOperationLock $bulkLock,
36	    ) {}
37	
38	    /**
39	     * Execute a GraphQL request against the Shopify Admin API.
40	     *
41	     * Pre-acquires from the local token bucket before sending and reconciles
42	     * bucket state from the authoritative throttleStatus in the response.
43	     *
44	     * @throws ShopifyGraphQLException top-level GraphQL errors (excluding THROTTLED)
45	     * @throws ShopifyTransportException non-2xx HTTP, timeout, or connection failure
46	     */
47	    public function graphql(
48	        string $shopDomain,
49	        string $accessToken,
50	        string $apiVersion,
51	        string $query,
52	        array $variables = [],
53	        ?int $timeoutSeconds = null,
54	    ): Response {
55	        $timeout = $timeoutSeconds ?? (int) config('services.shopify.throttle.default_timeout', 20);
56	        $maxRetries = (int) config('services.shopify.throttle.max_inprocess_retries', 3);
57	        $maxWait = (int) config('services.shopify.throttle.max_wait_ms', 5000);
58	        $queryHash = sha1($query);
59	        $attempt = 0;
60	
61	        while (true) {
62	            $this->preAcquireBudget($shopDomain, $queryHash);
63	            $started = microtime(true);
64	            $response = $this->post($shopDomain, $accessToken, $apiVersion, $query, $variables, $timeout);
65	            $this->reconcileFromResponse($response, $shopDomain, $queryHash, $started);
66	
67	            if ($this->isThrottled($response)) {
68	                $wait = $this->throttleWaitMs($response, $maxWait);
69	                if ($attempt >= $maxRetries) {
70	                    throw new ShopifyThrottledException($shopDomain, $wait, $attempt, $queryHash);
71	                }
72	                $this->metrics->throttled($shopDomain, $wait, $attempt + 1);
73	                // Blocks the worker thread — keep max_inprocess_retries low (default 3).
74	                usleep($wait * 1000);
75	                $attempt++;
76	
77	                continue;
78	            }
79	
80	            $this->handleGraphqlErrors($response, $shopDomain, $queryHash);
81	
82	            return $response;
83	        }
84	    }
85	
86	    /**
87	     * Execute a REST request against the Shopify Admin API.
88	     *
89	     * REST throttling is bucket-based (40 calls on standard, 80 on Plus) and
90	     * signalled via HTTP 429 + Retry-After. Low-volume in our codebase so we
91	     * only react to 429 rather than pre-throttling.
92	     *
93	     * @param  string  $method  'GET'|'POST'|'PUT'|'DELETE'
94	     * @param  string  $path  must start with `/admin/...`
