100	    public function rest(
101	        string $method,
102	        string $shopDomain,
103	        string $accessToken,
104	        string $path,
105	        array $body = [],
106	        ?int $timeoutSeconds = null,
107	        bool $allow401 = false,
108	    ): Response {
109	        $timeout = $timeoutSeconds ?? (int) config('services.shopify.throttle.default_timeout', 20);
110	        $maxRetries = (int) config('services.shopify.throttle.max_inprocess_retries', 3);
111	        $url = "https://{$shopDomain}{$path}";
112	
113	        $attempt = 0;
114	        while (true) {
115	            try {
116	                $pending = Http::withHeaders(['X-Shopify-Access-Token' => $accessToken])->timeout($timeout);
117	                $response = match (strtoupper($method)) {
118	                    'GET' => $pending->get($url, $body),
119	                    'POST' => $pending->post($url, $body),
120	                    'PUT' => $pending->put($url, $body),
121	                    'DELETE' => $pending->delete($url, $body),
122	                    default => throw new \InvalidArgumentException("Unsupported HTTP method: {$method}"),
123	                };
124	            } catch (ConnectionException $e) {
125	                throw new ShopifyTransportException($shopDomain, 0, $e->getMessage(), $e);
126	            }
127	
128	            if ($response->status() === 429 && $attempt < $maxRetries) {
129	                $wait = max(1000, ((int) ($response->header('Retry-After') ?? 1)) * 1000);
130	                $this->metrics->throttled($shopDomain, $wait, $attempt + 1);
131	                // Blocks the worker thread — keep max_inprocess_retries low (default 3).
132	                usleep($wait * 1000);
133	                $attempt++;
134	
135	                continue;
136	            }
137	
138	            if ($response->successful()) {
139	                return $response;
140	            }
141	
142	            if ($allow401 && $response->status() === 401) {
143	                return $response;
144	            }
145	
146	            throw new ShopifyTransportException($shopDomain, $response->status(), (string) $response->body());
