239	    /**
240	     * Poll a bulk operation until it reaches a terminal state.
241	     * Releases the per-shop bulk lock on terminal state.
242	     *
243	     * WARNING: synchronous — blocks the Horizon worker for up to $timeoutSeconds.
244	     * Run in a dedicated long-running job, not an inline service call.
245	     *
246	     * @return array{status: string, url: string|null, error_code: string|null}
247	     */
248	    public function waitForBulkOperation(
249	        string $shopDomain,
250	        string $accessToken,
251	        string $apiVersion,
252	        string $operationId,
253	        int $pollIntervalMs = 2000,
254	        int $timeoutSeconds = 600,
255	    ): array {
256	        $query = <<<'GRAPHQL'
257	        query bulkOperationStatus($id: ID!) {
258	          node(id: $id) { ... on BulkOperation { id status errorCode url } }
259	        }
260	        GRAPHQL;
261	
262	        $deadline = microtime(true) + $timeoutSeconds;
263	        $terminal = ['COMPLETED', 'FAILED', 'CANCELED', 'EXPIRED'];
264	
265	        while (microtime(true) < $deadline) {
266	            try {
267	                $response = $this->graphql($shopDomain, $accessToken, $apiVersion, $query, ['id' => $operationId]);
268	            } catch (\Throwable $e) {
269	                $this->bulkLock->release($shopDomain);
270	                throw $e;
271	            }
272	            $node = $response->json('data.node', []);
273	            $status = (string) ($node['status'] ?? 'UNKNOWN');
274	
275	            if (in_array($status, $terminal, true)) {
276	                $this->bulkLock->release($shopDomain);
277	
278	                return [
279	                    'status' => $status,
280	                    'url' => $node['url'] ?? null,
281	                    'error_code' => $node['errorCode'] ?? null,
282	                ];
283	            }
284	
285	            usleep($pollIntervalMs * 1000);
286	        }
287	
288	        // Timed out before terminal — release lock so shop isn't stuck
289	        $this->bulkLock->release($shopDomain);
290	        throw new \RuntimeException("Shopify bulk operation {$operationId} on {$shopDomain} timed out after {$timeoutSeconds}s");
291	    }
