345	    /**
346	     * Returns how long to wait before retrying a THROTTLED response, in milliseconds.
347	     * Falls back to 1 000 ms (capped at max_wait_ms) when no throttleStatus is available.
348	     */
349	    private function throttleWaitMs(Response $response, int $maxWait): int
350	    {
351	        $available = $response->json('extensions.cost.throttleStatus.currentlyAvailable');
352	        $restoreRate = $response->json('extensions.cost.throttleStatus.restoreRate');
353	
354	        if ($restoreRate > 0 && $available !== null) {
355	            // Estimate how many ms until 10 points are available (minimum useful budget)
356	            $needed = max(0, 10 - (int) $available);
357	            $waitMs = (int) ceil(($needed / $restoreRate) * 1000);
358	
359	            return min($waitMs, $maxWait);
360	        }
361	
362	        return min(1000, $maxWait);
363	    }
