392	    /**
393	     * Overwrite local bucket state with Shopify's authoritative throttleStatus
394	     * and record the actual/requested cost ratio for future estimates.
395	     */
396	    private function reconcileFromResponse(Response $response, string $shopDomain, string $queryHash, float $started): void
397	    {
398	        $cost = $response->json('extensions.cost');
399	        if (! is_array($cost)) {
400	            return;
401	        }
402	
403	        $status = $cost['throttleStatus'] ?? [];
404	        if (isset($status['currentlyAvailable'])) {
405	            $this->budget->reconcile(
406	                $shopDomain,
407	                (int) $status['currentlyAvailable'],
408	            );
409	        }
410	
411	        $requested = (int) ($cost['requestedQueryCost'] ?? 0);
412	        $actual = (int) ($cost['actualQueryCost'] ?? 0);
413	        if ($requested > 0 && $actual > 0) {
414	            $this->cost->record($queryHash, $requested, $actual);
415	        }
416	
417	        $this->metrics->request(
418	            $shopDomain,
419	            $queryHash,
420	            (microtime(true) - $started) * 1000,
421	            $actual,
422	            (int) ($status['currentlyAvailable'] ?? 0), // 0 when throttleStatus absent — not a true empty-bucket signal
423	        );
424	    }
